def calculate_S(N):
    S = 0
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            S += (a * b) // (N + 1)
    return S

def calculate_T(N):
    return (N**3 - N**2 + 2) / 4

N_values = [1, 2, 3, 4]
results = {}
for N in N_values:
    S_N = calculate_S(N)
    T_N = calculate_T(N)
    match = S_N == T_N
    results[N] = {
        "S(N)": S_N,
        "T(N)": T_N,
        "Match": match
    }

print("--- Results ---")
for N, res in results.items():
    print(f"N={N}:")
    print(f"  S({N}) = {res['S(N)']}")
    print(f"  T({N}) = {res['T(N)']}")
    print(f"  Match: {res['Match']}")

